package domain

import (
	"github.com/google/uuid"
)

// IdempotencyKey is a Value Object representing an idempotency key.
// It is immutable after creation and validated in the constructor.
// The idempotency key ALWAYS comes from the client via the HTTP request header
// (X-Idempotency-Key), passed through the Kafka event. It is NOT generated by the system.
//
// When provided, it must be a valid UUID v4 format.
// Returns error if validation fails.
//
// The idempotency key does NOT participate in deduplication.
// Deduplication is performed exclusively via (captured_at, event_id) constraint.
// The idempotency key serves for client-side deduplication tracking only.
//
// RF: RF-02 (Validation), RF-03 (Idempotency)
type IdempotencyKey struct {
	value string // Always a valid UUID v4 string
}

// NewIdempotencyKey creates a new IdempotencyKey from a client-provided string.
// The value MUST be provided - it comes from the HTTP X-Idempotency-Key header.
// If the input is nil or empty string, returns error (required from client).
// If the input is a non-empty string, validates it as UUID v4 format.
// Returns error if validation fails.
func NewIdempotencyKey(keyStr *string) (IdempotencyKey, error) {
	// IdempotencyKey is required - must come from client
	if keyStr == nil || *keyStr == "" {
		return IdempotencyKey{}, NewAppError(
			"MISSING_IDEMPOTENCY_KEY",
			"idempotency_key is required and must be provided by the client",
			nil,
		)
	}

	// Validate format: must be a valid UUID v4
	parsed, err := uuid.Parse(*keyStr)
	if err != nil {
		return IdempotencyKey{}, NewAppError(
			"INVALID_IDEMPOTENCY_KEY",
			"idempotency_key must be a valid UUID v4",
			err,
		)
	}

	// Verify it's v4
	if parsed.Version() != 4 {
		return IdempotencyKey{}, NewAppError(
			"INVALID_IDEMPOTENCY_KEY",
			"idempotency_key must be a UUID v4",
			nil,
		)
	}

	return IdempotencyKey{value: parsed.String()}, nil
}

// String returns the IdempotencyKey as a string.
func (i IdempotencyKey) String() string {
	return i.value
}
